    @_mutmut_mutated(mutants_xǁPRReviewerǁ_analyze_file__mutmut)
    def _analyze_file(self, file_path: str, diff: str) -> list[ReviewComment]:
        """단일 파일 분석"""
        comments = []

        # diff에서 추가된 라인만 추출
        added_lines = self._extract_added_lines(diff)

        # 패턴 매칭
        for line_num, line_content in added_lines:
            for (
                pattern,
                category,
                rule_id,
                message,
                severity,
                suggestion,
            ) in self.all_patterns:
                matches = pattern.finditer(line_content)
                for match in matches:
                    comments.append(
                        ReviewComment(
                            file_path=file_path,
                            line_start=line_num,
                            line_end=line_num,
                            severity=severity,
                            category=category,
                            title=f"[{category.value.upper()}] {rule_id}",
                            message=message,
                            suggestion=suggestion,
                            rule_id=rule_id,
                        )
                    )

        return comments

