    @_mutmut_mutated(mutants_xǁPRReviewerǁ_extract_added_lines__mutmut)
    def _extract_added_lines(self, diff: str) -> list[tuple[int, str]]:
        """diff에서 추가된 라인 추출 (라인 번호 포함)"""
        added = []
        current_line = 0

        for line in diff.split("\n"):
            if line.startswith("@@"):
                # @@ -old_start,old_count +new_start,new_count @@
                match = re.search(r"\+(\d+)", line)
                if match:
                    current_line = int(match.group(1)) - 1
            elif line.startswith("+"):
                current_line += 1
                # diff 헤더 라인 제외 (+++ b/file.py)
                if not line.startswith("+++"):
                    added.append((current_line, line[1:]))
            elif line.startswith("-"):
                # 삭제된 라인은 라인 번호만 증가
                pass
            else:
                current_line += 1

        return added

