    @_mutmut_mutated(mutants_xǁPRReviewerǁ_run_static_analysis__mutmut)
    def _run_static_analysis(self, file_paths: list[str]) -> list[ReviewComment]:
        """정적 분석 도구 실행 (ruff, mypy)"""
        comments = []

        # ruff 실행
        try:
            result = subprocess.run(
                ["ruff", "check", "--output-format=json"] + file_paths,
                capture_output=True,
                text=True,
                timeout=120,
                cwd=self.workspace,
                check=False,
            )
            if result.stdout:
                import json

                issues = json.loads(result.stdout)
                for issue in issues:
                    loc = issue.get("location", {})
                    end_loc = issue.get("end_location", {})
                    line_start = loc.get("row", 1)
                    line_end = end_loc.get("row", line_start)
                    comments.append(
                        ReviewComment(
                            file_path=issue["filename"],
                            line_start=line_start,
                            line_end=line_end,
                            severity=self._map_ruff_severity(issue.get("level", "warning")),
                            category=ReviewCategory.STYLE,
                            title=f"[RUFF] {issue['code']}",
                            message=issue["message"],
                            rule_id=issue["code"],
                        )
                    )
        except (OSError, subprocess.SubprocessError, json.JSONDecodeError) as e:
            log.warning(f"ruff 실행 실패: {e}")

        # mypy 실행
        try:
            result = subprocess.run(
                ["mypy", "--explicit-package-bases", "--json"] + file_paths,
                capture_output=True,
                text=True,
                timeout=120,
                cwd=self.workspace,
                check=False,
            )
            if result.stdout:
                import json

                issues = json.loads(result.stdout)
                for issue in issues:
                    comments.append(
                        ReviewComment(
                            file_path=issue["file"],
                            line_start=issue["line"],
                            line_end=issue.get("end_line", issue["line"]),
                            severity=ReviewSeverity.WARNING,
                            category=ReviewCategory.STYLE,
                            title=f"[MYPY] {issue.get('code', 'type-error')}",
                            message=issue["message"],
                            rule_id=issue.get("code", "type-error"),
                        )
                    )
        except (OSError, subprocess.SubprocessError, json.JSONDecodeError) as e:
            log.warning(f"mypy 실행 실패: {e}")

        return comments

